from typing import Dict, List
import math
from services.rag import Rag
from services.calculations.portfolio import get_portfolio_summary
from services.calculations.debt import get_debt_summary

class Retriever:
    def __init__(self, rag: Rag):
        self.rag = rag

    def retrieve(self, query: str, k: int = 5) -> List[str]:
        return self.rag.retrieve(query, k)

class Personalizer:
    def __init__(self, llm_client):
        self.llm_client = llm_client

    def personalize(self, summary: Dict[str, float]) -> List[str]:
        topics = []
        if summary.get('debt_ratio', 0) > 0.5:
            topics.append("Managing Debt")
        if summary.get('investment_return', 0) < 0:
            topics.append("Investment Losses")
        if summary.get('cash_flow', 0) < 0:
            topics.append("Cash Flow Management")
        return topics

    def get_lesson_text(self, topic: str) -> str:
        if topic == "Managing Debt":
            return "Learn how to manage your debt effectively."
        elif topic == "Investment Losses":
            return "Understand the reasons behind investment losses."
        elif topic == "Cash Flow Management":
            return "Master the art of cash flow management."
        return "No relevant lessons available."

class LearningSpecialist:
    def __init__(self, llm_client):
        self.retriever = Retriever(Rag())
        self.personalizer = Personalizer(llm_client)

    def get_topics(self, summary: Dict[str, float]) -> List[str]:
        topics = self.personalizer.personalize(summary)
        return topics

    def get_topic_text(self, topic: str) -> str:
        return self.personalizer.get_lesson_text(topic)
